using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace Great.Parts.Cel.Eng.Checks;

/// <summary>
/// Reads a generated file outside the allowed directories as one form: the signs are the marker comment and the name, the
/// reason is the comments before the first token of the file without the marker tags, the place is the comment with the marker
/// or <c>(1,1)</c> (<c>docs/design/eng-checks-source.md</c>, "Generated code" and "suppressions"). A generated file in an allowed
/// directory is outside every check. <c>[GeneratedCode]</c> is a form of the C# scanner.
/// </summary>
internal sealed class GeneratedFileSuppressionScanner : ISuppressionScanner
{
    private const string Key = "generated";
    private static readonly string[] TagNames = ["auto-generated", "autogenerated"];

    /// <inheritdoc/>
    public IEnumerable<SuppressionForm> Scan(CheckContext context) => context.Sources.GeneratedFiles
        .Where(file => !file.Allowed)
        .Select(file => new SuppressionForm(
            file.Path,
            file.Position,
            file.HasMarker ? "generated file (auto-generated marker)" : "generated file (generated name)",
            "reason comment before the first token",
            [Key],
            [],
            string.Join(' ', file.Comments.Select(comment => RemoveMarkerTags(comment.Text)))));

    // The tags <auto-generated…>, </auto-generated>, <autogenerated…> and </autogenerated> are not a reason: each goes
    // from '<' to the next '>', or to the end of the line when the tag is not closed there. The names are case-sensitive,
    // like the marker.
    private static string RemoveMarkerTags(string text)
    {
        StringBuilder result = new(text.Length);
        int index = 0;
        while (index < text.Length)
        {
            int tag = NextTag(text, index);
            if (tag < 0)
            {
                result.Append(text, index, text.Length - index);
                break;
            }

            result.Append(text, index, tag - index);
            index = TagEnd(text, tag);
        }

        return result.ToString();
    }

    private static int NextTag(string text, int from)
    {
        for (int open = text.IndexOf('<', from); open >= 0; open = text.IndexOf('<', open + 1))
        {
            int name = open + 1 < text.Length && text[open + 1] == '/' ? open + 2 : open + 1;
            if (TagNames.Any(tagName => string.CompareOrdinal(text, name, tagName, 0, tagName.Length) == 0))
            {
                return open;
            }
        }

        return -1;
    }

    private static int TagEnd(string text, int open)
    {
        int end = text.AsSpan(open).IndexOfAny('>', '\r', '\n');
        if (end < 0)
        {
            return text.Length;
        }

        return text[open + end] == '>' ? open + end + 1 : open + end;
    }
}
